def pairwise_comparison(objects, comparisons):
  # Initialize a dictionary to store the rankings
  rankings = {}
  for i, obj in enumerate(objects):
    rankings[obj] = 0
  # Loop through the comparisons and update the rankings
  for obj1, obj2, result in comparisons:
    if result == '>':
      rankings[obj1] += 1
    elif result == '<':
      rankings[obj2] += 1
  # Sort the objects by their rankings and return the sorted list
  sorted_objects = sorted(objects, key=lambda x: rankings[x], reverse=True)
  return sorted_objects

